// Cobblemon settings we change (config.js), applied when the server loads instead of shipping Cobblemon's whole
// config/cobblemon/main.json (118 settings, regenerated by every Cobblemon update).
// - PC boxes: Cobblemon 1.8.4 gives every new PC 40 boxes; we give 60. PCs are created on a player's first join.
// - Wild spawn rarity (DESIGN.md, "Wild spawn rarity"): our odds are in config/cobblemon/spawning/
//   best-spawner-config.json, which Cobblemon only reads when exportSpawnConfig is on, and only at startup. Switch it on
//   and reload the spawner config here, before anyone joins: each player's spawner copies the odds when they log in.
//   (`/cobblemonconfig reload` re-reads main.json, where it's off, so the default odds come back until a restart.)

const $CobblemonMain = Java.loadClass('com.cobblemon.mod.common.Cobblemon')

ServerEvents.loaded(event => {
  let config = $CobblemonMain.INSTANCE.config
  config.defaultBoxCount = global.campfiremonsConfig.pcBoxes
  console.info(`[campfiremons] Cobblemon PC boxes per new PC: ${config.defaultBoxCount}`)

  config.exportSpawnConfig = true
  let spawner = $CobblemonMain.INSTANCE.bestSpawner
  spawner.reloadConfig()
  console.info(`[campfiremons] wild spawn odds: ${spawner.config.worldBuckets}`)
})
